input.command:
cd /Users/raman/projects/lock_code_manager.wiki && git status --short; grep -n "^#\{1,2\} \|Managing-Guests-and-Rentals-Recipes\|Managing-Guests-and-Rentals#" Managing-Guests-and-Rentals.md Managing-Guests-and-Rentals-Recipes.md | head -40; /usr/bin/python3 - <<'EOF'
import re
pages={'Managing-Guests-and-Rentals':open('Managing-Guests-and-Rentals.md').read(),'Managing-Guests-and-Rentals-Recipes':open('Managing-Guests-and-Rentals-Recipes.md').read()}
def slug(h): return re.sub(r'[^a-z0-9 _-]','',h.strip().lower()).replace(' ','-')
anchors={p:{slug(m) for m in re.findall(r'^#+ (.*)$',t,re.M)} for p,t in pages.items()}
for p,t in pages.items():
    for page,a in re.findall(r'\[\[[^|\]]*\|?(Managing-Guests-and-Rentals(?:-Recipes)?)?#([a-z0-9_-]+)\]\]',t)+[(p,a) for a in re.findall(r'\]\(#([a-z0-9_-]+)\)',t)]:
        page=page or p
        print(('ok ' if a in anchors.get(page,set()) else 'BROKEN '),p,'->',page+'#'+a)
EOF

