/usr/bin/python3 - <<'PYEOF'
p='blueprints/template/lock_code_manager/calendar_condition.yaml'; s=open(p).read()
def rep(a,b):
    global s; assert s.count(a)==1,a[:70]; s=s.replace(a,b)
rep("""    {%- set has_name = name not in ('', 'unknown', 'unavailable') -%}
    {%- if match == 'any' -%}
      {%- set matched = true -%}
    {%- elif match == 'name_in_title' -%}
      {%- set matched = has_name and name in title -%}
    {%- elif match == 'name_in_description' -%}
      {%- set matched = has_name and name in details -%}
""","""    {#- Names match as whole words: punctuation and spacing become single
        spaces on both sides, so "Al" doesn't match "Alice". -#}
    {%- set words = ' ' ~ (name | regex_replace('\\\\W+', ' ') | trim) ~ ' ' -%}
    {%- set has_name = name not in ('unknown', 'unavailable')
        and words | trim != '' -%}
    {%- set title_words = ' ' ~ (title | regex_replace('\\\\W+', ' ')) ~ ' ' -%}
    {%- set details_words = ' ' ~ (details | regex_replace('\\\\W+', ' ')) ~ ' ' -%}
    {%- if match == 'any' -%}
      {%- set matched = true -%}
    {%- elif match == 'name_in_title' -%}
      {%- set matched = has_name and words in title_words -%}
    {%- elif match == 'name_in_description' -%}
      {%- set matched = has_name and words in details_words -%}
""")
open(p,'w').write(s)
PYEOF
grep -n "regex_replace" blueprints/template/lock_code_manager/calendar_condition.yaml; ../../.venv/bin/python -m pytest tests/test_blueprint_behavior.py -k calendar_condition -p no:cacheprovider -q 2>&1 | grep -E "passed|failed|^FAILED|Warning"

